fn put(o:[*]u8,p:usize,x:f64)void{const bits:u64=@bitCast(x);for(0..8)|k|o[p+k]=@truncate(bits>>@intCast(8*k));}
fn absf(x:f64)f64{return if(x<0)-x else x;}
export fn gauss_jordan(v:[*c]const i64,n:usize,o:[*c]u8,cap:usize)i64{if(v==null or n<2 or n>22)return -1;const rr=v[0];const cc=v[1];if(rr<1 or rr>4 or cc<1 or cc>4)return -1;const r:usize=@intCast(rr);const c:usize=@intCast(cc);if(n!=2+r*c+r)return -1;var a=[_] [4]f64{.{0} ** 4} ** 4;var b=[_]f64{0} ** 4;for(0..r)|i|{for(0..c)|j|{const z=v[2+i*c+j];if(z < -5000 or z>5000)return -1;a[i][j]=@as(f64,@floatFromInt(z))/1000.0;}const z=v[2+r*c+i];if(z < -5000 or z>5000)return -1;b[i]=@as(f64,@floatFromInt(z))/1000.0;}const bytes=(r*c+r)*8;for(0..c)|col|{var pivot:?usize=null;for(col..r)|row|{if(absf(a[row][col])>1e-8){pivot=row;break;}}if(pivot==null)continue;const pr=pivot.?;if(pr!=col){const tmp=a[pr];a[pr]=a[col];a[col]=tmp;const tb=b[pr];b[pr]=b[col];b[col]=tb;}const pv=a[col][col];for(0..c)|j|a[col][j]/=pv;b[col]/=pv;for(0..r)|row|{if(row==col)continue;const factor=a[row][col];for(0..c)|j|a[row][j]-=factor*a[col][j];b[row]-=factor*b[col];}}if(o==null or cap<bytes)return -2;var at:usize=0;for(0..r)|i|{for(0..c)|j|{put(o,at*8,a[i][j]);at+=1;}}for(0..r)|i|{put(o,at*8,b[i]);at+=1;}return @intCast(bytes);}
